public static final boolean isContiguous(ReadablePartial partial) {
    if (partial == null) {
        throw new IllegalArgumentException("Partial cannot be null");
    }
    Chronology chrono = getChronology(partial.getChronology());
    int size = partial.size();
    if (size < 2) {
        return true;
    }
    DurationField lastUnit = null;
    for (int i = size - 1; i >= 0; i--) {
        DateTimeField field = chrono.getField(partial.getFieldType(i));
        DurationField range = field.getRangeDurationField();
        if (lastUnit != null && (range == null || !range.equals(lastUnit))) {
            return false;
        }
        lastUnit = field.getDurationField();
    }
    return true;
}
